mapper.update:
update pay_order
set status = 'CLOSE', update_time = now()
where user_id = #{userId}
  and order_id = #{orderId}
  and status = #{expectedStatus}
  and status in ('CREATE', 'PAY_WAIT')

update pay_order
set status = 'WAIT_REFUND', update_time = now()
where user_id = #{userId}
  and order_id = #{orderId}
  and status = #{expectedStatus}
  and status in ('PAY_SUCCESS', 'MARKET', 'DEAL_DONE')

mapper.select:
select id, user_id, product_id, product_name, order_id, order_time,
       total_amount, status, pay_url, pay_time, market_type,
       activity_id, team_id, market_deduction_amount, pay_amount
from pay_order
where user_id = #{userId}

  and id < #{lastId}

order by id desc
limit #{limit}

select user_id, order_id, status, market_type, team_id from pay_order where team_id = #{teamId} and market_type = 1 and status in ('PAY_SUCCESS', 'MARKET', 'DEAL_DONE') and order_id in
#{orderId}
for update
